CREATE TABLE sources(id TEXT PRIMARY KEY, adapter TEXT NOT NULL, status TEXT NOT NULL, cadence_seconds INTEGER, config_hash TEXT, credential_status TEXT, last_error TEXT, last_success_at TEXT);
CREATE TABLE source_routes(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), lane TEXT, market TEXT, query_text TEXT, next_due_at TEXT, last_attempt_at TEXT, last_success_at TEXT, completed_through TEXT, incomplete_reason TEXT);
CREATE TABLE source_runs(id INTEGER PRIMARY KEY, route_id TEXT REFERENCES source_routes(id), started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, physical_requests INTEGER NOT NULL DEFAULT 0, records_returned INTEGER NOT NULL DEFAULT 0, error TEXT);
CREATE TABLE search_windows(id TEXT PRIMARY KEY, route_id TEXT REFERENCES source_routes(id), frozen_start TEXT, frozen_end TEXT, continuation_json TEXT NOT NULL, complete INTEGER NOT NULL DEFAULT 0, last_durable_page INTEGER NOT NULL DEFAULT 0, incomplete_reason TEXT, legacy_origin TEXT);
CREATE TABLE listings(id INTEGER PRIMARY KEY, platform TEXT NOT NULL, platform_key TEXT NOT NULL, external_id TEXT NOT NULL, variation_id TEXT NOT NULL DEFAULT '', seller TEXT, canonical_url TEXT, title TEXT NOT NULL, description TEXT, listing_type TEXT NOT NULL DEFAULT 'UNKNOWN', first_seen_at TEXT, imported INTEGER NOT NULL DEFAULT 0, availability TEXT NOT NULL DEFAULT 'UNKNOWN', processing TEXT NOT NULL DEFAULT 'CAPTURED', current_observation_id INTEGER, triage_score INTEGER, triage_reason TEXT, photographer TEXT, core_tier TEXT, verdict TEXT, last_triaged_at TEXT, UNIQUE(platform,platform_key));
CREATE TABLE listing_aliases(id INTEGER PRIMARY KEY, listing_id INTEGER NOT NULL REFERENCES listings(id), alias_type TEXT NOT NULL, alias TEXT NOT NULL, source_id TEXT, provenance TEXT, confidence TEXT NOT NULL DEFAULT 'EXACT', UNIQUE(alias_type,alias));
CREATE TABLE observations(id INTEGER PRIMARY KEY, listing_id INTEGER NOT NULL REFERENCES listings(id), origin_key TEXT NOT NULL UNIQUE, observed_at TEXT, captured_at TEXT NOT NULL, price_minor INTEGER, currency TEXT, shipping_minor INTEGER, shipping_currency TEXT, auction_end_at TEXT, bid_count INTEGER, available TEXT, content_hash TEXT NOT NULL, raw_json TEXT NOT NULL);
CREATE TABLE book_records(id INTEGER PRIMARY KEY, record_key TEXT NOT NULL UNIQUE, contributor TEXT, title TEXT, tier TEXT, provenance TEXT, raw_json TEXT NOT NULL);
CREATE TABLE recognition_matches(id INTEGER PRIMARY KEY, listing_id INTEGER NOT NULL REFERENCES listings(id), book_record_key TEXT, contributor TEXT, score INTEGER, reason TEXT, source TEXT, matched_at TEXT, UNIQUE(listing_id,book_record_key,source));
CREATE TABLE jobs(id INTEGER PRIMARY KEY, job_key TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, listing_id INTEGER REFERENCES listings(id), route_id TEXT REFERENCES source_routes(id), priority INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'PENDING', due_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, lease_token TEXT, lease_owner TEXT, lease_until TEXT, last_error TEXT, payload_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE reviews(id INTEGER PRIMARY KEY, listing_id INTEGER NOT NULL REFERENCES listings(id), observation_id INTEGER REFERENCES observations(id), provider TEXT, policy_hash TEXT, verdict TEXT, confidence TEXT, status TEXT NOT NULL, started_at TEXT, finished_at TEXT, result_json TEXT);
CREATE TABLE evidence(id INTEGER PRIMARY KEY, listing_id INTEGER REFERENCES listings(id), review_id INTEGER REFERENCES reviews(id), url TEXT, retrieved_at TEXT, evidence_type TEXT, supported_field TEXT, claim_kind TEXT, excerpt TEXT);
CREATE TABLE user_decisions(id INTEGER PRIMARY KEY, listing_id INTEGER NOT NULL REFERENCES listings(id), action TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL, undone_at TEXT, imported INTEGER NOT NULL DEFAULT 0);
CREATE TABLE notification_events(id INTEGER PRIMARY KEY, event_key TEXT NOT NULL UNIQUE, listing_id INTEGER REFERENCES listings(id), stage TEXT NOT NULL, channel TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'QUEUED', created_at TEXT NOT NULL, expires_at TEXT, attempts INTEGER NOT NULL DEFAULT 0, lease_token TEXT, lease_until TEXT, provider_request TEXT, provider_receipt TEXT, accepted_at TEXT, acknowledged_at TEXT, suppression_reason TEXT, last_error TEXT);
CREATE TABLE api_windows(id INTEGER PRIMARY KEY, bucket TEXT NOT NULL, window_start TEXT NOT NULL, reset_at TEXT NOT NULL, provider_limit INTEGER NOT NULL, consumed INTEGER NOT NULL DEFAULT 0, reserved INTEGER NOT NULL DEFAULT 0, uncertain INTEGER NOT NULL DEFAULT 0, provider_remaining INTEGER, UNIQUE(bucket,window_start));
CREATE TABLE api_requests(id INTEGER PRIMARY KEY, window_id INTEGER NOT NULL REFERENCES api_windows(id), route_id TEXT, reason TEXT, reserved_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, response_class TEXT);
CREATE TABLE imports(id INTEGER PRIMARY KEY, origin TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, byte_size INTEGER NOT NULL, rows_total INTEGER NOT NULL DEFAULT 0, rows_mapped INTEGER NOT NULL DEFAULT 0, rows_quarantined INTEGER NOT NULL DEFAULT 0, rows_nonlisting INTEGER NOT NULL DEFAULT 0, completed_at TEXT, error TEXT);
CREATE TABLE legacy_objects(id INTEGER PRIMARY KEY, import_id INTEGER REFERENCES imports(id), object_key TEXT NOT NULL UNIQUE, listing_id INTEGER REFERENCES listings(id), object_type TEXT NOT NULL, parse_status TEXT NOT NULL, source_timestamp TEXT, raw_json TEXT, error TEXT);
CREATE TABLE app_events(id INTEGER PRIMARY KEY, at TEXT NOT NULL, kind TEXT NOT NULL, detail_json TEXT NOT NULL);
CREATE TABLE instance_leases(name TEXT PRIMARY KEY, owner TEXT NOT NULL, generation INTEGER NOT NULL, lease_until TEXT NOT NULL);
CREATE TABLE health(key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX listings_find_idx ON listings(processing,triage_score DESC,id DESC);
CREATE INDEX listings_urgent_idx ON listings(listing_type,availability,id DESC);
CREATE INDEX listings_title_idx ON listings(title COLLATE NOCASE);
CREATE INDEX jobs_due_idx ON jobs(status,due_at,priority DESC);
CREATE INDEX notifications_due_idx ON notification_events(status,created_at);
CREATE INDEX observations_listing_idx ON observations(listing_id,observed_at DESC);
CREATE INDEX legacy_listing_idx ON legacy_objects(listing_id);
